  TH_T(420,y[0]+56,'driven by',{fs:24,fw:800,fill:ORG})+TH_T(420,y[0]+88,TH_sub('T','1')+' > '+TH_sub('T','2'),{fs:26,fw:800,fill:ORG});
 /* 2 work: piston, shaft, current */
